#[cfg(test)]
mod tests {
    use super::*;

    /// Every icon path resolves to a themeable SVG. A typo in the generated
    /// registry is otherwise invisible until the button renders blank.
    #[test]
    fn every_icon_resolves_to_themeable_svg() {
        for icon in ALL {
            let bytes =
                asset(icon.path()).unwrap_or_else(|| panic!("{} has no bytes", icon.path()));
            let text = std::str::from_utf8(bytes).expect("icon is UTF-8");
            assert!(text.contains("<svg"), "{} is not an SVG", icon.path());
            // currentColor is what lets a glyph take the surrounding ink — a
            // hardcoded fill would ignore the theme and the accent.
            assert!(
                text.contains("currentColor"),
                "{} must stroke/fill with currentColor to be themeable",
                icon.path()
            );
        }
        assert!(asset("icons/replace.svg").is_none());
    }
}
